using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestDbContextHelper
    {
        public static SchoolContext CreateContext(string? dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;

            var context = new SchoolContext(options);
            return context;
        }

        public static SchoolContext CreateSeededContext(string? dbName = null)
        {
            var context = CreateContext(dbName);
            SeedData(context);
            return context;
        }

        public static void SeedData(SchoolContext context)
        {
            var instructor1 = new Instructor
            {
                FirstMidName = "Kim",
                LastName = "Abercrombie",
                HireDate = DateTime.Parse("1995-03-11")
            };
            var instructor2 = new Instructor
            {
                FirstMidName = "Fadi",
                LastName = "Fakhouri",
                HireDate = DateTime.Parse("2002-07-06")
            };

            context.Instructors.AddRange(instructor1, instructor2);
            context.SaveChanges();

            var department1 = new Department
            {
                Name = "English",
                Budget = 350000,
                StartDate = DateTime.Parse("2007-09-01"),
                InstructorID = instructor1.ID
            };
            var department2 = new Department
            {
                Name = "Mathematics",
                Budget = 100000,
                StartDate = DateTime.Parse("2007-09-01"),
                InstructorID = instructor2.ID
            };

            context.Departments.AddRange(department1, department2);
            context.SaveChanges();

            var course1 = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = department1.DepartmentID
            };
            var course2 = new Course
            {
                CourseID = 4022,
                Title = "Microeconomics",
                Credits = 3,
                DepartmentID = department2.DepartmentID
            };

            context.Courses.AddRange(course1, course2);
            context.SaveChanges();

            var student1 = new Student
            {
                FirstMidName = "Carson",
                LastName = "Alexander",
                EnrollmentDate = DateTime.Parse("2010-09-01")
            };
            var student2 = new Student
            {
                FirstMidName = "Meredith",
                LastName = "Alonso",
                EnrollmentDate = DateTime.Parse("2012-09-01")
            };
            var student3 = new Student
            {
                FirstMidName = "Arturo",
                LastName = "Anand",
                EnrollmentDate = DateTime.Parse("2013-09-01")
            };

            context.Students.AddRange(student1, student2, student3);
            context.SaveChanges();

            context.Enrollments.Add(new Enrollment
            {
                StudentID = student1.ID,
                CourseID = course1.CourseID,
                Grade = Grade.A
            });
            context.SaveChanges();

            // Add course assignments
            context.CourseAssignments.Add(new CourseAssignment
            {
                CourseID = course1.CourseID,
                InstructorID = instructor1.ID
            });
            context.SaveChanges();

            // Add office assignment
            context.OfficeAssignments.Add(new OfficeAssignment
            {
                InstructorID = instructor2.ID,
                Location = "Smith 17"
            });
            context.SaveChanges();
        }
    }
}

using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Constructor_WithItems_SetsPageIndexAndTotalPages()
        {
            // Arrange
            var items = new List<string> { "a", "b", "c" };

            // Act
            var result = new PaginatedList<string>(items, 10, 2, 3);

            // Assert
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(4, result.TotalPages); // ceil(10/3) = 4
            Assert.Equal(3, result.Count);
            Assert.Equal("a", result[0]);
            Assert.Equal("b", result[1]);
            Assert.Equal("c", result[2]);
        }

        [Theory]
        [InlineData(10, 1, 5, 2)]   // 10 items, page 1, pageSize 5 -> 2 total pages
        [InlineData(10, 2, 5, 2)]   // 10 items, page 2, pageSize 5 -> 2 total pages
        [InlineData(11, 1, 5, 3)]   // 11 items, page 1, pageSize 5 -> 3 total pages (ceil)
        [InlineData(1, 1, 10, 1)]   // 1 item, page 1, pageSize 10 -> 1 total page
        [InlineData(0, 1, 10, 0)]   // 0 items, page 1, pageSize 10 -> 0 total pages
        public void Constructor_CalculatesTotalPages_Correctly(int count, int pageIndex, int pageSize, int expectedTotalPages)
        {
            // Arrange & Act
            var result = new PaginatedList<int>(new List<int>(), count, pageIndex, pageSize);

            // Assert
            Assert.Equal(expectedTotalPages, result.TotalPages);
            Assert.Equal(pageIndex, result.PageIndex);
        }

        [Fact]
        public void HasPreviousPage_FirstPage_ReturnsFalse()
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), 20, 1, 10);

            // Act & Assert
            Assert.False(list.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_SecondPage_ReturnsTrue()
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), 20, 2, 10);

            // Act & Assert
            Assert.True(list.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_LastPage_ReturnsFalse()
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), 20, 2, 10);

            // Act & Assert
            Assert.False(list.HasNextPage);
        }

        [Fact]
        public void HasNextPage_FirstPageOfMultiple_ReturnsTrue()
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), 20, 1, 10);

            // Act & Assert
            Assert.True(list.HasNextPage);
        }

        [Fact]
        public void HasNextPage_SinglePage_ReturnsFalse()
        {
            // Arrange
            var list = new PaginatedList<int>(new List<int>(), 5, 1, 10);

            // Act & Assert
            Assert.False(list.HasNextPage);
        }

        [Fact]
        public void Create_ReturnsCorrectPageOfData()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 2, 10);

            // Assert
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(3, result.TotalPages); // ceil(25/10) = 3
            Assert.Equal(10, result.Count);
            Assert.Equal(11, result[0]); // second page starts at 11
            Assert.Equal(20, result[9]); // second page ends at 20
        }

        [Fact]
        public void Create_LastPage_ReturnsRemainingItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 3, 10);

            // Assert
            Assert.Equal(3, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
            Assert.Equal(5, result.Count); // only 5 items on last page
            Assert.Equal(21, result[0]);
            Assert.Equal(25, result[4]);
        }

        [Fact]
        public void Create_FirstPage_SkipsNothing()
        {
            // Arrange
            var source = Enumerable.Range(1, 15).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(2, result.TotalPages);
