using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            _context = TestDbContextHelper.CreateSeededContext();
            _controller = new NotificationsController(_context);
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(),
                new SessionStateTempDataProvider(new SessionStateTempDataSerializer()));
            // Drain static queue
            var svc = new ContosoUniversity.Services.NotificationService();
            while (svc.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain queue to prevent cross-test contamination
            var svc = new ContosoUniversity.Services.NotificationService();
            while (svc.ReceiveNotification() != null) { }
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsView()
        {
            // Act
            var result = _controller.Index() as ViewResult;

            // Assert
            Assert.NotNull(result);
        }

        [Fact]
        public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
        {
            // Act
            var result = _controller.GetNotifications() as JsonResult;

            // Assert
            Assert.NotNull(result);
            var value = result.Value;
            Assert.NotNull(value);
            // Check properties via reflection since it's an anonymous type
            var successProp = value.GetType().GetProperty("success");
            Assert.NotNull(successProp);
            Assert.True((bool)successProp.GetValue(value)!);
            var countProp = value.GetType().GetProperty("count");
            Assert.Equal(0, (int)countProp!.GetValue(value)!);
        }

        [Fact]
        public void GetNotifications_WithNotifications_ReturnsNotifications()
        {
            // Arrange - send some notifications via the service
            var svc = new ContosoUniversity.Services.NotificationService();
            svc.SendNotification("Student", "1", "Test Student", EntityOperation.CREATE, "admin");
            svc.SendNotification("Course", "2", "Math 101", EntityOperation.UPDATE, "admin");

            // Act
            var result = _controller.GetNotifications() as JsonResult;

            // Assert
            Assert.NotNull(result);
            var value = result.Value!;
            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp!.GetValue(value)!);
            var countProp = value.GetType().GetProperty("count");
            Assert.Equal(2, (int)countProp!.GetValue(value)!);
        }

        [Fact]
        public void GetNotifications_LimitsTo10()
        {
            // Arrange - send more than 10 notifications
            var svc = new ContosoUniversity.Services.NotificationService();
            for (int i = 0; i < 15; i++)
            {
                svc.SendNotification("Student", i.ToString(), EntityOperation.CREATE);
            }

            // Act
            var result = _controller.GetNotifications() as JsonResult;

            // Assert
            Assert.NotNull(result);
            var value = result.Value!;
            var countProp = value.GetType().GetProperty("count");
            Assert.Equal(10, (int)countProp!.GetValue(value)!);
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccess()
        {
            // Act
            var result = _controller.MarkAsRead(1) as JsonResult;

            // Assert
            Assert.NotNull(result);
            var value = result.Value!;
            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp!.GetValue(value)!);
        }
    }
}

