        [Theory]
        [InlineData(".jpg", true)]
        [InlineData(".jpeg", true)]
        [InlineData(".png", true)]
        [InlineData(".gif", true)]
        [InlineData(".bmp", true)]
        [InlineData(".exe", false)]
        [InlineData(".txt", false)]
        [InlineData(".pdf", false)]
        public void Create_Post_FileExtensionValidation_WorksCorrectly(string extension, bool shouldPass)
        {
            // Arrange
            var course = new Course
            {
                CourseID = 7777,
                Title = "Test Course",
                Credits = 3,
                DepartmentID = _context.Departments.First().DepartmentID
            };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns($"test{extension}");
            mockFile.Setup(f => f.Length).Returns(1024);

            if (shouldPass)
            {
                // For valid extensions, mock CopyTo to avoid actual file operations
                mockFile.Setup(f => f.CopyTo(It.IsAny<System.IO.Stream>()));
            }

            // Act
            var result = _controller.Create(course, mockFile.Object);

            // Assert
            if (shouldPass)
            {
                // Valid extensions should either redirect or return view (depending on file save success)
                // The important thing is NO "teachingMaterialImage" model error about extension
                var hasExtensionError = _controller.ModelState.ContainsKey("teachingMaterialImage") &&
                    _controller.ModelState["teachingMaterialImage"]!.Errors.Any(e => e.ErrorMessage.Contains("valid image"));
                Assert.False(hasExtensionError);
            }
            else
            {
                Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            }
        }
    }
}

