using ContosoUniversity.Models;
using ContosoUniversity.Services;
using System;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut;

        public NotificationServiceTests()
        {
            _sut = new NotificationService();
            // Drain the static queue to avoid cross-test contamination
            while (_sut.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain queue after test
            while (_sut.ReceiveNotification() != null) { }
            _sut.Dispose();
        }

        [Fact]
        public void SendNotification_WithDisplayName_CreatesNotificationWithCorrectMessage()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Contains("John Doe", notification.Message);
            Assert.Contains("created", notification.Message);
            Assert.Equal("admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesIdInMessage()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "42", EntityOperation.UPDATE, "user1");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("ID: 42", notification.Message);
            Assert.Contains("updated", notification.Message);
            Assert.Equal("user1", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_WithNullUserName_DefaultsToSystem()
        {
            // Arrange & Act
            _sut.SendNotification("Course", "10", EntityOperation.DELETE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "created")]
        [InlineData(EntityOperation.UPDATE, "updated")]
        [InlineData(EntityOperation.DELETE, "deleted")]
        public void SendNotification_DifferentOperations_GeneratesCorrectMessage(EntityOperation operation, string expectedVerb)
        {
            // Arrange & Act
            _sut.SendNotification("Department", "5", "Engineering", operation, "admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains(expectedVerb, notification.Message);
            Assert.Equal(operation.ToString(), notification.Operation);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToCurrentTime()
        {
            // Arrange
            var before = DateTime.Now;

            // Act
            _sut.SendNotification("Student", "1", EntityOperation.CREATE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.True(notification.CreatedAt >= before);
            Assert.True(notification.CreatedAt <= DateTime.Now);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            // Act
            var result = _sut.ReceiveNotification();

            // Assert
            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_MultipleMessages_ReturnsFIFO()
        {
            // Arrange
            _sut.SendNotification("Student", "1", EntityOperation.CREATE);
            _sut.SendNotification("Course", "2", EntityOperation.UPDATE);
            _sut.SendNotification("Department", "3", EntityOperation.DELETE);

            // Act & Assert
            var n1 = _sut.ReceiveNotification();
            Assert.Equal("Student", n1!.EntityType);

            var n2 = _sut.ReceiveNotification();
            Assert.Equal("Course", n2!.EntityType);

            var n3 = _sut.ReceiveNotification();
            Assert.Equal("Department", n3!.EntityType);

            var n4 = _sut.ReceiveNotification();
            Assert.Null(n4);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // Act & Assert - MarkAsRead is a no-op for in-memory implementation
            var exception = Record.Exception(() => _sut.MarkAsRead(1));
            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_WithEmptyDisplayName_UsesIdInMessage()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "99", "", EntityOperation.CREATE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("ID: 99", notification.Message);
        }

        [Fact]
        public void SendNotification_WithWhitespaceDisplayName_UsesIdInMessage()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "99", "   ", EntityOperation.UPDATE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("ID: 99", notification.Message);
        }

        [Fact]
        public void SendNotification_OverloadWithoutDisplayName_SetsCorrectFields()
        {
            // Arrange & Act
            _sut.SendNotification("Instructor", "7", EntityOperation.DELETE, "teacher");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Instructor", notification.EntityType);
            Assert.Equal("7", notification.EntityId);
            Assert.Equal("DELETE", notification.Operation);
            Assert.Equal("teacher", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void Dispose_CanBeCalledMultipleTimes()
        {
            // Act & Assert
            var sut = new NotificationService();
            var exception = Record.Exception(() =>
            {
                sut.Dispose();
                sut.Dispose();
            });
            Assert.Null(exception);
        }
    }
}

