            var instructor = new Instructor
            {
                FirstMidName = "ToDelete",
                LastName = "Deletable",
                HireDate = DateTime.Parse("2020-01-01"),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();
            // Add office assignment
            _context.OfficeAssignments.Add(new OfficeAssignment
            {
                InstructorID = instructor.ID,
                Location = "Room 101"
            });
            _context.SaveChanges();
            var initialCount = _context.Instructors.Count();

            // Act
            var result = _controller.DeleteConfirmed(instructor.ID) as RedirectToActionResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Equal(initialCount - 1, _context.Instructors.Count());
        }

        [Fact]
        public void DeleteConfirmed_InstructorWithDepartment_ClearsDepartmentReference()
        {
            // Arrange
            var instructor = _context.Instructors.First();
            // Ensure the instructor is referenced by a department
            var dept = _context.Departments.First(d => d.InstructorID == instructor.ID);
            Assert.NotNull(dept);

            // Need office assignment for the delete to work
            if (!_context.OfficeAssignments.Any(o => o.InstructorID == instructor.ID))
            {
                _context.OfficeAssignments.Add(new OfficeAssignment
                {
                    InstructorID = instructor.ID,
                    Location = "Temp"
                });
                _context.SaveChanges();
            }

            // Act
            var result = _controller.DeleteConfirmed(instructor.ID) as RedirectToActionResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            // Department should have InstructorID set to null
            var updatedDept = _context.Departments.Find(dept.DepartmentID);
            Assert.Null(updatedDept!.InstructorID);
        }
    }
