using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests
    {
        [Fact]
        public void SchoolContext_CanCreateWithInMemoryProvider()
        {
            // Arrange & Act
            using var context = TestDbContextHelper.CreateContext();

            // Assert
            Assert.NotNull(context);
            Assert.NotNull(context.Students);
            Assert.NotNull(context.Courses);
            Assert.NotNull(context.Departments);
            Assert.NotNull(context.Instructors);
            Assert.NotNull(context.Enrollments);
            Assert.NotNull(context.OfficeAssignments);
            Assert.NotNull(context.CourseAssignments);
            Assert.NotNull(context.Notifications);
            Assert.NotNull(context.People);
        }

        [Fact]
        public void SchoolContext_CanAddAndRetrieveStudent()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = DateTime.Parse("2023-01-01")
            };

            // Act
            context.Students.Add(student);
            context.SaveChanges();

            // Assert
            var retrieved = context.Students.Single();
            Assert.Equal("Test", retrieved.FirstMidName);
            Assert.Equal("Student", retrieved.LastName);
            Assert.Equal(DateTime.Parse("2023-01-01"), retrieved.EnrollmentDate);
        }

        [Fact]
        public void SchoolContext_CourseAssignment_HasCompositeKey()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateSeededContext();

            // Act - Add a course assignment
            var instructor = context.Instructors.First();
            var course = context.Courses.First();

            // The composite key is (CourseID, InstructorID)
            var assignment = context.CourseAssignments
                .FirstOrDefault(ca => ca.CourseID == course.CourseID && ca.InstructorID == instructor.ID);

            // Assert
            Assert.NotNull(assignment);
            Assert.Equal(course.CourseID, assignment.CourseID);
            Assert.Equal(instructor.ID, assignment.InstructorID);
        }

        [Fact]
        public void SchoolContext_StudentInheritsFromPerson()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Person",
                EnrollmentDate = DateTime.Parse("2023-01-01")
            };

            // Act
            context.Students.Add(student);
            context.SaveChanges();

            // Assert - student should be accessible via People DbSet
            var person = context.People.First();
            Assert.IsType<Student>(person);
            Assert.Equal("Person", person.LastName);
        }

        [Fact]
        public void SchoolContext_InstructorInheritsFromPerson()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Prof",
                HireDate = DateTime.Parse("2023-01-01")
            };

            // Act
            context.Instructors.Add(instructor);
            context.SaveChanges();

            // Assert
            var person = context.People.First();
            Assert.IsType<Instructor>(person);
            Assert.Equal("Prof", person.LastName);
        }

        [Fact]
        public void SchoolContext_CanAddNotification()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();
            var notification = new Notification
            {
                EntityType = "Student",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test notification",
                CreatedAt = DateTime.Now,
                CreatedBy = "admin",
                IsRead = false
            };

            // Act
            context.Notifications.Add(notification);
            context.SaveChanges();

            // Assert
            var saved = context.Notifications.Single();
            Assert.Equal("Student", saved.EntityType);
            Assert.Equal("1", saved.EntityId);
            Assert.Equal("CREATE", saved.Operation);
            Assert.Equal("Test notification", saved.Message);
            Assert.Equal("admin", saved.CreatedBy);
            Assert.False(saved.IsRead);
        }

        [Fact]
        public void SchoolContext_OfficeAssignment_OneToOneWithInstructor()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateSeededContext();

            // Act
            var instructor = context.Instructors
                .Include(i => i.OfficeAssignment)
                .First(i => i.LastName == "Fakhouri");

            // Assert
            Assert.NotNull(instructor.OfficeAssignment);
            Assert.Equal("Smith 17", instructor.OfficeAssignment.Location);
            Assert.Equal(instructor.ID, instructor.OfficeAssignment.InstructorID);
        }
    }
}

