 using Microsoft.AspNetCore.Mvc.ViewFeatures;
 using Microsoft.Extensions.Logging;
 using Moq;
 using System;
 using System.Collections.Generic;
 using System.Linq;
 using Xunit;

 namespace ContosoUniversity.Tests.Controllers
 {
     public class CoursesControllerTests : IDisposable
     {
         private readonly SchoolContext _context;
         private readonly CoursesController _controller;
         private readonly Mock<IWebHostEnvironment> _mockEnv;
         private readonly Mock<ILogger<CoursesController>> _mockLogger;

         public CoursesControllerTests()
         {
             _context = TestDbContextHelper.CreateSeededContext();
             _mockEnv = new Mock<IWebHostEnvironment>();
             _mockEnv.Setup(e => e.WebRootPath).Returns(System.IO.Path.GetTempPath());
             _mockEnv.Setup(e => e.ContentRootPath).Returns(System.IO.Path.GetTempPath());
             _mockLogger = new Mock<ILogger<CoursesController>>();
             _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
             _controller.TempData = new TempDataDictionary(
                 new DefaultHttpContext(),
                 new SessionStateTempDataProvider(new SessionStateTempDataSerializer()));
         }

         public void Dispose()
         {
             _controller.Dispose();
             _context.Dispose();
         }

         [Fact]
         public void Index_ReturnsViewWithAllCourses()
         {
             // Act
             var result = _controller.Index() as ViewResult;

             // Assert
             Assert.NotNull(result);
             var model = result.Model as List<Course>;
             Assert.NotNull(model);
             Assert.Equal(2, model.Count); // 2 seeded courses
         }

         [Fact]
         public void Details_ValidId_ReturnsViewWithCourse()
         {
             // Arrange
             var course = _context.Courses.First();

             // Act
             var result = _controller.Details(course.CourseID) as ViewResult;

             // Assert
             Assert.NotNull(result);
             var model = result.Model as Course;
             Assert.NotNull(model);
             Assert.Equal(course.CourseID, model.CourseID);
             Assert.Equal(course.Title, model.Title);
         }

         [Fact]
         public void Details_NullId_ReturnsBadRequest()
         {
             // Act
             var result = _controller.Details(null) as StatusCodeResult;

             // Assert
             Assert.NotNull(result);
             Assert.Equal(400, result.StatusCode);
         }

         [Fact]
         public void Create_Get_ReturnsViewWithNewCourse()
         {
             // Act
             var result = _controller.Create() as ViewResult;

             // Assert
             Assert.NotNull(result);
             var model = result.Model as Course;
             Assert.NotNull(model);
         }

         [Fact]
         public void Create_Post_ValidCourse_NoFile_RedirectsToIndex()
         {
             // Arrange
             var course = new Course
             {
                 CourseID = 9999,
                 Title = "New Course",
                 Credits = 3,
                 DepartmentID = _context.Departments.First().DepartmentID
             };

             // Act
             var result = _controller.Create(course, null!) as RedirectToActionResult;

             // Assert
             Assert.NotNull(result);
             Assert.Equal("Index", result.ActionName);
             Assert.Equal(3, _context.Courses.Count());
             var saved = _context.Courses.Find(9999);
             Assert.NotNull(saved);
             Assert.Equal("New Course", saved.Title);
             Assert.Equal(3, saved.Credits);
         }

         [Fact]
         public void Create_Post_InvalidModel_ReturnsView()
         {
             // Arrange
             _controller.ModelState.AddModelError("Title", "Required");
             var course = new Course();

             // Act
             var result = _controller.Create(course, null!) as ViewResult;

             // Assert
             Assert.NotNull(result);
         }

         [Fact]
         public void Create_Post_InvalidFileExtension_ReturnsViewWithError()
         {
             // Arrange
             var course = new Course
             {
                 CourseID = 8888,
                 Title = "Test",
                 Credits = 3,
                 DepartmentID = _context.Departments.First().DepartmentID
             };
             var mockFile = new Mock<IFormFile>();
             mockFile.Setup(f => f.FileName).Returns("test.exe");
             mockFile.Setup(f => f.Length).Returns(1024);

             // Act
             var result = _controller.Create(course, mockFile.Object) as ViewResult;

             // Assert
             Assert.NotNull(result);
             Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
         }

         [Fact]
         public void Create_Post_FileTooLarge_ReturnsViewWithError()
         {
             // Arrange
             var course = new Course
             {
                 CourseID = 8888,
                 Title = "Test",
                 Credits = 3,
                 DepartmentID = _context.Departments.First().DepartmentID
             };
             var mockFile = new Mock<IFormFile>();
             mockFile.Setup(f => f.FileName).Returns("test.jpg");
             mockFile.Setup(f => f.Length).Returns(10 * 1024 * 1024); // 10MB > 5MB limit

             // Act
             var result = _controller.Create(course, mockFile.Object) as ViewResult;

             // Assert
             Assert.NotNull(result);
             Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
         }

         [Fact]
         public void Edit_Get_ValidId_ReturnsViewWithCourse()
         {
             // Arrange
             var course = _context.Courses.First();

             // Act
             var result = _controller.Edit(course.CourseID) as ViewResult;

             // Assert
             Assert.NotNull(result);
             var model = result.Model as Course;
             Assert.NotNull(model);
             Assert.Equal(course.CourseID, model.CourseID);
         }

         [Fact]
         public void Edit_Get_NullId_ReturnsBadRequest()
         {
             // Act
             var result = _controller.Edit(null) as StatusCodeResult;

             // Assert
             Assert.NotNull(result);
             Assert.Equal(400, result.StatusCode);
         }

         [Fact]
         public void Edit_Get_InvalidId_ReturnsNotFound()
         {
             // Act
             var result = _controller.Edit(99999) as NotFoundResult;

             // Assert
             Assert.NotNull(result);
         }

         [Fact]
         public void Edit_Post_ValidCourse_NoFile_RedirectsToIndex()
         {
             // Arrange
             var existing = _context.Courses.First();
             var course = new Course
             {
                 CourseID = existing.CourseID,
                 Title = "Updated Title",
                 Credits = 4,
                 DepartmentID = existing.DepartmentID
             };
             _context.Entry(existing).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

             // Act
             var result = _controller.Edit(course, null!) as RedirectToActionResult;

             // Assert
             Assert.NotNull(result);
             Assert.Equal("Index", result.ActionName);
         }

         [Fact]
         public void Edit_Post_InvalidFileExtension_ReturnsViewWithError()
         {
             // Arrange
             var existing = _context.Courses.First();
             var course = new Course
             {
                 CourseID = existing.CourseID,
                 Title = existing.Title,
                 Credits = existing.Credits,
                 DepartmentID = existing.DepartmentID
             };
             var mockFile = new Mock<IFormFile>();
             mockFile.Setup(f => f.FileName).Returns("test.txt");
             mockFile.Setup(f => f.Length).Returns(1024);

             // Act
             var result = _controller.Edit(course, mockFile.Object) as ViewResult;

             // Assert
             Assert.NotNull(result);
             Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
         }

         [Fact]
         public void Edit_Post_FileTooLarge_ReturnsViewWithError()
         {
             // Arrange
             var existing = _context.Courses.First();
             var course = new Course
             {
                 CourseID = existing.CourseID,
                 Title = existing.Title,
                 Credits = existing.Credits,
                 DepartmentID = existing.DepartmentID
             };
             var mockFile = new Mock<IFormFile>();
             mockFile.Setup(f => f.FileName).Returns("test.png");
             mockFile.Setup(f => f.Length).Returns(6 * 1024 * 1024); // 6MB > 5MB limit

             // Act
             var result = _controller.Edit(course, mockFile.Object) as ViewResult;

             // Assert
             Assert.NotNull(result);
             Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
         }

         [Fact]
         public void Delete_Get_ValidId_ReturnsViewWithCourse()
         {
             // Arrange
             var course = _context.Courses.First();

             // Act
             var result = _controller.Delete(course.CourseID) as ViewResult;

             // Assert
             Assert.NotNull(result);
             var model = result.Model as Course;
             Assert.NotNull(model);
             Assert.Equal(course.CourseID, model.CourseID);
         }

         [Fact]
         public void Delete_Get_NullId_ReturnsBadRequest()
         {
             // Act
             var result = _controller.Delete(null) as StatusCodeResult;

             // Assert
             Assert.NotNull(result);
             Assert.Equal(400, result.StatusCode);
         }

         [Fact]
         public void DeleteConfirmed_ValidId_RemovesCourseAndRedirects()
         {
             // Arrange
             var course = _context.Courses.First();
             var initialCount = _context.Courses.Count();

             // Act
             var result = _controller.DeleteConfirmed(course.CourseID) as RedirectToActionResult;

             // Assert
             Assert.NotNull(result);
             Assert.Equal("Index", result.ActionName);
             Assert.Equal(initialCount - 1, _context.Courses.Count());
         }

         [Theory]
         [InlineData(".jpg", true)]
         [InlineData(".jpeg", true)]
         [InlineData(".png", true)]
         [InlineData(".gif", true)]
         [InlineData(".bmp", true)]
         [InlineData(".exe", false)]
         [InlineData(".txt", false)]
         [InlineData(".pdf", false)]
         public void Create_Post_FileExtensionValidation_WorksCorrectly(string extension, bool shouldPass)
         {
             // Arrange
             var course = new Course
             {
                 CourseID = 7777,
                 Title = "Test Course",
                 Credits = 3,
                 DepartmentID = _context.Departments.First().DepartmentID
             };
             var mockFile = new Mock<IFormFile>();
             mockFile.Setup(f => f.FileName).Returns($"test{extension}");
             mockFile.Setup(f => f.Length).Returns(1024);

             if (shouldPass)
             {
                 // For valid extensions, mock CopyTo to avoid actual file operations
                 mockFile.Setup(f => f.CopyTo(It.IsAny<System.IO.Stream>()));
             }

             // Act
             var result = _controller.Create(course, mockFile.Object);

             // Assert
             if (shouldPass)
             {
                 // Valid extensions should either redirect or return view (depending on file save success)
                 // The important thing is NO "teachingMaterialImage" model error about extension
                 var hasExtensionError = _controller.ModelState.ContainsKey("teachingMaterialImage") &&
                     _controller.ModelState["teachingMaterialImage"]!.Errors.Any(e => e.ErrorMessage.Contains("valid image"));
                 Assert.False(hasExtensionError);
             }
             else
             {
                 Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
             }
         }
     }
 }

