 using ContosoUniversity.Controllers;
 using ContosoUniversity.Data;
 using ContosoUniversity.Models;
 using ContosoUniversity.Models.SchoolViewModels;
 using ContosoUniversity.Tests.Helpers;
 using Microsoft.AspNetCore.Http;
 using Microsoft.AspNetCore.Mvc;
 using Microsoft.AspNetCore.Mvc.ViewFeatures;
 using System;
 using System.Collections.Generic;
 using System.Linq;
 using Xunit;

 namespace ContosoUniversity.Tests.Controllers
 {
     public class InstructorsControllerTests : IDisposable
     {
         private readonly SchoolContext _context;
         private readonly InstructorsController _controller;

         public InstructorsControllerTests()
         {
             _context = TestDbContextHelper.CreateSeededContext();
             _controller = new InstructorsController(_context);
             _controller.TempData = new TempDataDictionary(
                 new DefaultHttpContext(),
                 new SessionStateTempDataProvider(new SessionStateTempDataSerializer()));
         }

         public void Dispose()
         {
             _controller.Dispose();
             _context.Dispose();
         }

         [Fact]
         public void Index_NoParameters_ReturnsViewWithInstructors()
         {
             // Act
             var result = _controller.Index(null, null) as ViewResult;

             // Assert
             Assert.NotNull(result);
             var model = result.Model as InstructorIndexData;
             Assert.NotNull(model);
             Assert.Equal(2, model.Instructors.Count()); // 2 seeded instructors
         }

         [Fact]
         public void Index_WithInstructorId_PopulatesCourses()
         {
             // Arrange
             var instructor = _context.Instructors.First();

             // Act
             var result = _controller.Index(instructor.ID, null) as ViewResult;

             // Assert
             Assert.NotNull(result);
             var model = result.Model as InstructorIndexData;
             Assert.NotNull(model);
             Assert.NotNull(model.Courses);
         }

         [Fact]
         public void Details_ValidId_ReturnsViewWithInstructor()
         {
             // Arrange
             var instructor = _context.Instructors.First();

             // Act
             var result = _controller.Details(instructor.ID) as ViewResult;

             // Assert
             Assert.NotNull(result);
             var model = result.Model as Instructor;
             Assert.NotNull(model);
             Assert.Equal(instructor.ID, model.ID);
             Assert.Equal(instructor.LastName, model.LastName);
             Assert.Equal(instructor.FirstMidName, model.FirstMidName);
         }

         [Fact]
         public void Details_NullId_ReturnsBadRequest()
         {
             // Act
             var result = _controller.Details(null) as StatusCodeResult;

             // Assert
             Assert.NotNull(result);
             Assert.Equal(400, result.StatusCode);
         }

         [Fact]
         public void Details_InvalidId_ReturnsNotFound()
         {
             // Act
             var result = _controller.Details(99999) as NotFoundResult;

             // Assert
             Assert.NotNull(result);
         }

         [Fact]
         public void Create_Get_ReturnsViewWithInstructor()
         {
             // Act
             var result = _controller.Create() as ViewResult;

             // Assert
             Assert.NotNull(result);
             var model = result.Model as Instructor;
             Assert.NotNull(model);
             Assert.NotNull(model.CourseAssignments);
             Assert.Empty(model.CourseAssignments);
         }

         [Fact]
         public void Create_Post_ValidInstructor_RedirectsToIndex()
         {
             // Arrange
             var instructor = new Instructor
             {
                 FirstMidName = "New",
                 LastName = "Instructor",
                 HireDate = DateTime.Parse("2023-01-15"),
                 CourseAssignments = new List<CourseAssignment>()
             };

             // Act
             var result = _controller.Create(instructor, null!) as RedirectToActionResult;

             // Assert
             Assert.NotNull(result);
             Assert.Equal("Index", result.ActionName);
             Assert.Equal(3, _context.Instructors.Count());
             var saved = _context.Instructors.Single(i => i.LastName == "Instructor");
             Assert.Equal("New", saved.FirstMidName);
             Assert.Equal(DateTime.Parse("2023-01-15"), saved.HireDate);
         }

         [Fact]
         public void Create_Post_WithSelectedCourses_CreatesCourseAssignments()
         {
             // Arrange
             var instructor = new Instructor
             {
                 FirstMidName = "New",
                 LastName = "WithCourses",
                 HireDate = DateTime.Parse("2023-01-15")
             };
             var courseId = _context.Courses.First().CourseID.ToString();

             // Act
             var result = _controller.Create(instructor, new[] { courseId }) as RedirectToActionResult;

             // Assert
             Assert.NotNull(result);
             Assert.Equal("Index", result.ActionName);
             var saved = _context.Instructors.Single(i => i.LastName == "WithCourses");
             var assignments = _context.CourseAssignments.Where(ca => ca.InstructorID == saved.ID).ToList();
             Assert.Single(assignments);
         }

         [Fact]
         public void Create_Post_InvalidModel_ReturnsView()
         {
             // Arrange
             _controller.ModelState.AddModelError("LastName", "Required");
             var instructor = new Instructor
             {
                 CourseAssignments = new List<CourseAssignment>()
             };

             // Act
             var result = _controller.Create(instructor, null!) as ViewResult;

             // Assert
             Assert.NotNull(result);
         }

         [Fact]
         public void Delete_Get_ValidId_ReturnsViewWithInstructor()
         {
             // Arrange
             var instructor = _context.Instructors.First();

             // Act
             var result = _controller.Delete(instructor.ID) as ViewResult;

             // Assert
             Assert.NotNull(result);
             var model = result.Model as Instructor;
             Assert.NotNull(model);
             Assert.Equal(instructor.ID, model.ID);
         }

         [Fact]
         public void Delete_Get_NullId_ReturnsBadRequest()
         {
             // Act
             var result = _controller.Delete(null) as StatusCodeResult;

             // Assert
             Assert.NotNull(result);
             Assert.Equal(400, result.StatusCode);
         }

         [Fact]
         public void Delete_Get_InvalidId_ReturnsNotFound()
         {
             // Act
             var result = _controller.Delete(99999) as NotFoundResult;

             // Assert
             Assert.NotNull(result);
         }

         [Fact]
         public void DeleteConfirmed_ValidId_RemovesInstructorAndRedirects()
         {
             // Arrange - use instructor without course assignments or department references
             var instructor = new Instructor
             {
                 FirstMidName = "ToDelete",
                 LastName = "Deletable",
                 HireDate = DateTime.Parse("2020-01-01"),
                 CourseAssignments = new List<CourseAssignment>()
             };
             _context.Instructors.Add(instructor);
             _context.SaveChanges();
             // Add office assignment
             _context.OfficeAssignments.Add(new OfficeAssignment
             {
                 InstructorID = instructor.ID,
                 Location = "Room 101"
             });
             _context.SaveChanges();
             var initialCount = _context.Instructors.Count();

             // Act
             var result = _controller.DeleteConfirmed(instructor.ID) as RedirectToActionResult;

             // Assert
             Assert.NotNull(result);
             Assert.Equal("Index", result.ActionName);
             Assert.Equal(initialCount - 1, _context.Instructors.Count());
         }

         [Fact]
         public void DeleteConfirmed_InstructorWithDepartment_ClearsDepartmentReference()
         {
             // Arrange
             var instructor = _context.Instructors.First();
             // Ensure the instructor is referenced by a department
             var dept = _context.Departments.First(d => d.InstructorID == instructor.ID);
             Assert.NotNull(dept);

             // Need office assignment for the delete to work
             if (!_context.OfficeAssignments.Any(o => o.InstructorID == instructor.ID))
             {
                 _context.OfficeAssignments.Add(new OfficeAssignment
                 {
                     InstructorID = instructor.ID,
                     Location = "Temp"
                 });
                 _context.SaveChanges();
             }

             // Act
             var result = _controller.DeleteConfirmed(instructor.ID) as RedirectToActionResult;

             // Assert
             Assert.NotNull(result);
             Assert.Equal("Index", result.ActionName);
             // Department should have InstructorID set to null
             var updatedDept = _context.Departments.Find(dept.DepartmentID);
             Assert.Null(updatedDept!.InstructorID);
         }
     }
 }

