[Fact]
public void SchoolContext_CourseAssignment_HasCompositeKey()
{
    // Arrange
    using var context = TestDbContextHelper.CreateSeededContext();

    // Act - Add a course assignment
    var instructor = context.Instructors.First();
    var course = context.Courses.First();

    // The composite key is (CourseID, InstructorID)
    var assignment = context.CourseAssignments
        .FirstOrDefault(ca => ca.CourseID == course.CourseID && ca.InstructorID == instructor.ID);

    // Assert
    Assert.NotNull(assignment);
    Assert.Equal(course.CourseID, assignment.CourseID);
    Assert.Equal(instructor.ID, assignment.InstructorID);
}

