[Fact]
public void SchoolContext_CourseAssignment_HasCompositeKey()
{
    // Arrange
    using var context = TestDbContextHelper.CreateSeededContext();

    // Act - Query existing course assignments from seed data
    var assignment = context.CourseAssignments.First();

    // Assert - Verify the composite key fields are populated
    Assert.True(assignment.CourseID > 0);
    Assert.True(assignment.InstructorID > 0);

    // Verify we can look up by composite key
    var lookedUp = context.CourseAssignments
        .FirstOrDefault(ca => ca.CourseID == assignment.CourseID && ca.InstructorID == assignment.InstructorID);
    Assert.NotNull(lookedUp);
    Assert.Equal(assignment.CourseID, lookedUp.CourseID);
    Assert.Equal(assignment.InstructorID, lookedUp.InstructorID);
}

