1. using ContosoUniversity.Models;
2. using ContosoUniversity.Services;
3. using System;
4. using Xunit;
5. 
6. namespace ContosoUniversity.Tests.Services
7. {
8.     public class NotificationServiceTests : IDisposable
9.     {
10.         private readonly NotificationService _sut;
11. 
12.         public NotificationServiceTests()
13.         {
14.             _sut = new NotificationService();
15.             // Drain the static queue to avoid cross-test contamination
16.             while (_sut.ReceiveNotification() != null) { }
17.         }
18. 
19.         public void Dispose()
20.         {
21.             // Drain queue after test
22.             while (_sut.ReceiveNotification() != null) { }
23.             _sut.Dispose();
24.         }
25. 
26.         [Fact]
27.         public void SendNotification_WithDisplayName_CreatesNotificationWithCorrectMessage()
28.         {
29.             // Arrange & Act
30.             _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "admin");
31. 
32.             // Assert
33.             var notification = _sut.ReceiveNotification();
34.             Assert.NotNull(notification);
35.             Assert.Equal("Student", notification.EntityType);
36.             Assert.Equal("1", notification.EntityId);
37.             Assert.Equal("CREATE", notification.Operation);
38.             Assert.Contains("John Doe", notification.Message);
39.             Assert.Contains("created", notification.Message);
40.             Assert.Equal("admin", notification.CreatedBy);
41.             Assert.False(notification.IsRead);
42.         }
43. 
44.         [Fact]
45.         public void SendNotification_WithoutDisplayName_UsesIdInMessage()
46.         {
47.             // Arrange & Act
48.             _sut.SendNotification("Student", "42", EntityOperation.UPDATE, "user1");
49. 
50.             // Assert
51.             var notification = _sut.ReceiveNotification();
52.             Assert.NotNull(notification);
53.             Assert.Contains("ID: 42", notification.Message);
54.             Assert.Contains("updated", notification.Message);
55.             Assert.Equal("user1", notification.CreatedBy);
56.         }
57. 
58.         [Fact]
59.         public void SendNotification_WithNullUserName_DefaultsToSystem()
60.         {
61.             // Arrange & Act
62.             _sut.SendNotification("Course", "10", EntityOperation.DELETE);
63. 
64.             // Assert
65.             var notification = _sut.ReceiveNotification();
66.             Assert.NotNull(notification);
67.             Assert.Equal("System", notification.CreatedBy);
68.         }
69. 
70.         [Theory]
71.         [InlineData(EntityOperation.CREATE, "created")]
72.         [InlineData(EntityOperation.UPDATE, "updated")]
73.         [InlineData(EntityOperation.DELETE, "deleted")]
74.         public void SendNotification_DifferentOperations_GeneratesCorrectMessage(EntityOperation operation, string expectedVerb)
75.         {
76.             // Arrange & Act
77.             _sut.SendNotification("Department", "5", "Engineering", operation, "admin");
78. 
79.             // Assert
80.             var notification = _sut.ReceiveNotification();
81.             Assert.NotNull(notification);
82.             Assert.Contains(expectedVerb, notification.Message);
83.             Assert.Equal(operation.ToString(), notification.Operation);
84.         }
85. 
86.         [Fact]
87.         public void SendNotification_SetsCreatedAtToCurrentTime()
88.         {
89.             // Arrange
90.             var before = DateTime.Now;
91. 
92.             // Act
93.             _sut.SendNotification("Student", "1", EntityOperation.CREATE);
94. 
95.             // Assert
96.             var notification = _sut.ReceiveNotification();
97.             Assert.NotNull(notification);
98.             Assert.True(notification.CreatedAt >= before);
99.             Assert.True(notification.CreatedAt <= DateTime.Now);
100.         }
101. 
102.         [Fact]
103.         public void ReceiveNotification_EmptyQueue_ReturnsNull()
104.         {
105.             // Act
106.             var result = _sut.ReceiveNotification();
107. 
108.             // Assert
109.             Assert.Null(result);
110.         }
111. 
112.         [Fact]
113.         public void ReceiveNotification_MultipleMessages_ReturnsFIFO()
114.         {
115.             // Arrange
116.             _sut.SendNotification("Student", "1", EntityOperation.CREATE);
117.             _sut.SendNotification("Course", "2", EntityOperation.UPDATE);
118.             _sut.SendNotification("Department", "3", EntityOperation.DELETE);
119. 
120.             // Act & Assert
121.             var n1 = _sut.ReceiveNotification();
122.             Assert.Equal("Student", n1!.EntityType);
123. 
124.             var n2 = _sut.ReceiveNotification();
125.             Assert.Equal("Course", n2!.EntityType);
126. 
127.             var n3 = _sut.ReceiveNotification();
128.             Assert.Equal("Department", n3!.EntityType);
129. 
130.             var n4 = _sut.ReceiveNotification();
131.             Assert.Null(n4);
132.         }
133. 
134.         [Fact]
135.         public void MarkAsRead_DoesNotThrow()
136.         {
137.             // Act & Assert - MarkAsRead is a no-op for in-memory implementation
138.             var exception = Record.Exception(() => _sut.MarkAsRead(1));
139.             Assert.Null(exception);
140.         }
141. 
142.         [Fact]
143.         public void SendNotification_WithEmptyDisplayName_UsesIdInMessage()
144.         {
145.             // Arrange & Act
146.             _sut.SendNotification("Student", "99", "", EntityOperation.CREATE);
147. 
